                                        @PathVariable String zoneKey,
                                        @RequestHeader("X-Actor-Id") String actor,
                                        @RequestBody ExemptionGrantRequest req) {
        return evacuation.grantExemption(incidentKey, zoneKey, actor, req);
    }

    /**
     * 查询事件全部撤离豁免（含区域版本）。
